def run(tree: pathlib.Path, tests: list[str], hang: float = HANG) -> int:
    """The tests' status: 124 for a hang, 125 when a process of the run outlived it
    (``tests/leaks.py``). Either way every process of the run is killed, in a new
    session or not, so no mutant leaves one behind."""
    # -B: a stale .pyc of an earlier mutant of the same size and second would be used.
    # No pipes: a holder a mutant leaves behind must not keep the run waiting.
    code, left = leaks.run([sys.executable, '-B', '-m', 'unittest', '-q', *tests], cwd=tree, timeout=hang,
                           quiet=True)
    return 125 if code == 0 and left else code


def one(tree: pathlib.Path, rel: str, old: str, new: str, tests: list[str]) -> tuple[bool, float]:
    """Whether the tests kill one mutant, and their time, applied to ``tree`` (one worker's own copy)."""
    path = tree / rel
    src = path.read_text()
    # the tests' own interpreters (the supervisor, the P2P self-test, run with -I) write
    # bytecode, and a mutant of the same size within the same second would load it: drop it
    cache = path.parent / '__pycache__'
    shutil.rmtree(cache, ignore_errors=True)
    path.write_text(src.replace(old, new))
    t0 = time.monotonic()
    try:
        return run(tree, tests) != 0, time.monotonic() - t0
    finally:
        path.write_text(src)
        shutil.rmtree(cache, ignore_errors=True)


def main() -> int:
    workers = max(1, min(WORKERS, os.cpu_count() or 1))
    with tempfile.TemporaryDirectory() as d:
        # main's state: a stamp PR's tree (operations §5 step 2) is stamped back to hook first, so
        # the snippets that name `@v1` are found there too
        base = pathlib.Path(d) / 'base'
        shutil.copytree(ROOT, base, ignore=shutil.ignore_patterns('.git', '__pycache__'))
        stamp.stamp(base, 'hook')
        for n, (rel, old, _new, _tests) in enumerate(MUTANTS, 1):
            count = (base / rel).read_text().count(old)
            if count != 1:
                print(f'mutant {n}: the snippet occurs {count} times in {rel}', file=sys.stderr)
                return 2
        trees = queue.SimpleQueue()
        for w in range(workers):  # a tree per worker: a mutant is never seen by another's tests
            tree = pathlib.Path(d) / f'tree{w}'
            shutil.copytree(base, tree)
            trees.put(tree)
        every = sorted({t for *_, ts in MUTANTS for t in ts})
        tree0 = trees.get()
        if run(tree0, every, hang=600):
            print('the unmutated tree fails its tests or leaves a process behind', file=sys.stderr)
            return 2
        trees.put(tree0)

        def job(m):
            tree = trees.get()
            try:
                return one(tree, *m)
            finally:
                trees.put(tree)
        with concurrent.futures.ThreadPoolExecutor(workers) as ex:
            killed = list(ex.map(job, MUTANTS))
    for n, ((rel, old, *_), (k, secs)) in enumerate(zip(MUTANTS, killed), 1):
        print(f'{"killed  " if k else "SURVIVED"} {n:3d} {secs:5.1f}s {rel}: {old.strip()[:70]!r}')
    survived = [k for k, _ in killed].count(False)
    print(f'{len(MUTANTS) - survived}/{len(MUTANTS)} mutants killed ({workers} workers)')
    return 1 if survived else 0


if __name__ == '__main__':
    sys.exit(main())
